    boolean replaced = false;
    if (canRefreshDelegationToken) {
      Token<?> token = getDelegationToken(null);
      LOG.debug("Replaced expired token: " + token);
      setDelegationToken(token);
      replaced = (token != null);
    }
    return replaced;
  }

